"""
    Input:
        args - variable number of integers represented as strings, e.g. to_list("15353", "025")

    Output:
        lst - a Python array of lists of strings, e.g. [[1,5,3,5,3],[0,2,5]]
    """
def to_list(*args: Any) -> object {
    lst = [];
    for string in args {
        lst.append([int(digit) for digit in string]);
    }
    return lst;
}

"""Takes a string representation of a comma separated list and returns a list
    of elements with trimmed whitespace.

    Args:
        raw (str): Comma separated list as a string.

    Returns:
        List[str]: List of trimmed strings.
    """
def parse_list(raw: Any) -> object {
    return [word.strip() for word in raw.split(",")];
}

