"""
    Create a return array and enumerate
    through the array and append it to
    the return array if the element is
    not a space( )
    """
def remove_spaces(data: Any) -> object {
    return_array = [];
    for (index, el) in enumerate(data) {
        if (el is not " ") {
            return_array.append(el);
        }
    }
    return return_array;
}

"""Return time stored in ar_filename, or 0.0 if it does not exist."""
def GetPersistTime(ar_filename: Any) -> object {
    try {
        with open(ar_filename) as f {
            return float(f.read());
        }
    } except (IOError, ValueError) {
        return 0.0;
    }
}

